def invers2(m):
    (a, b), (c, d) = m
    det = a * d - b * c
    if det == 0:
        return None
    return [[round(d / det + 0.0, 6), round(-b / det + 0.0, 6)], [round(-c / det + 0.0, 6), round(a / det + 0.0, 6)]]

